create index twin_assembly_part_identity on public.assembly_nodes(part_id);
create index twin_assembly_geometry_identity on public.assembly_nodes(geometry_revision_id);
create or replace function e34_private.twin_graph_row_immutable() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if exists(select 1 from public.digital_twin_configuration_revisions where publication_status='published' and (id=case when tg_op='INSERT' then new.configuration_revision_id else old.configuration_revision_id end or id=case when tg_op='DELETE' then old.configuration_revision_id else new.configuration_revision_id end)) then raise exception 'Create a new graph revision before editing published assembly metadata'; end if;
 return case when tg_op='DELETE' then old else new end;
end; $$;
